import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * A thread‑safe, XXE‑protected Atom provider.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared Abdera engine instance. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Whether to autodetect the character set from the XML declaration. */
    private boolean autodetectCharset;

    /* --------------------------------------------------------------------- */
    /* MessageBodyReader implementation                                       */
    /* --------------------------------------------------------------------- */

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a parser instance from the shared engine.
        Parser parser = ATOM_ENGINE.getParser();

        /*
         * Create a fresh ParserOptions instance for this request.  This guarantees
         * that the options are not shared between threads and that the
         * configuration is applied *before* parsing begins.
         */
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        options.setResolveEntities(false);          // Disable external entity resolution
        options.setAllowExternalEntities(false);     // Explicitly forbid external entities
        options.setNamespaceAware(true);             // Preserve namespace handling

        /*
         * Parse the incoming stream using the secure options.  The overloaded
         * parse method accepts a ParserOptions argument, ensuring that the
         * configuration is respected for this single parse operation.
         */
        Document<T> document;
        try {
            document = parser.parse(entityStream, options);
        } catch (org.apache.abdera.parser.ParserException e) {
            // Wrap parser exceptions as IOExceptions to satisfy the method signature.
            throw new IOException("Failed to parse Atom XML", e);
        }

        return document.getRoot();
    }

    /* --------------------------------------------------------------------- */
    /* Other methods omitted for brevity                                      */
    /* --------------------------------------------------------------------- */
}
```

