import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a sanitized name.
     * The method protects against directory‑traversal attacks by rejecting
     * names that contain path separators or relative components and by
     * verifying that the resulting canonical path resides within {@code dir}.
     *
     * @param dir  the target directory (must exist or be creatable)
     * @param name the requested file name (may come from untrusted sources)
     * @return a {@link File} object that does not conflict with existing files
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null}
     * @throws SecurityException        if the name would cause a path traversal
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Basic sanity checks – reject absolute paths, separators, or ".."
        if (name.contains("/") || name.contains("\\") || name.contains("..")) {
            throw new SecurityException("Invalid file name: " + name);
        }

        try {
            // Resolve the file and canonicalise paths
            File file = new File(dir, name);
            File canonicalFile = file.getCanonicalFile();
            File canonicalDir = dir.getCanonicalFile();

            // Ensure the file is inside the target directory
            String dirPath = canonicalDir.getPath();
            String filePath = canonicalFile.getPath();
            if (!filePath.startsWith(dirPath + File.separator)) {
                throw new SecurityException(
                        "Attempt to escape directory: " + name);
            }

            // Handle duplicate names by appending a numeric suffix
            String baseName = name;
            int dot = baseName.indexOf('.');
            String prefix = dot < 0 ? baseName : baseName.substring(0, dot);
            String suffix = dot < 0 ? "" : baseName.substring(dot);
            int index = 2;
            while (file.exists()) {
                String newName = prefix + "-" + index++ + suffix;
                file = new File(dir, newName);
                canonicalFile = file.getCanonicalFile(); // re‑check path safety
                if (!canonicalFile.getPath().startsWith(dirPath + File.separator)) {
                    throw new SecurityException(
                            "Attempt to escape directory during renaming: " + newName);
                }
            }

            // Ensure parent directories exist
            file.getParentFile().mkdirs();
            return file;
        } catch (IOException e) {
            // Wrap checked exception into an unchecked one for callers that
            // do not declare throws clauses. In production, consider logging.
            throw new IllegalStateException("Failed to allocate file", e);
        }
    }

