import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // ... other methods ...

    /**
     * Validates a media type token according to RFC 7230 §3.2.6.
     * A token consists of one or more tchar characters:
     *   tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" /
     *           "-" / "." / "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
     *
     * This method rejects null, empty strings, control characters,
     * whitespace, and any characters outside the allowed set, thereby
     * preventing HTTP header injection via malformed media type values.
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Allow the wildcard "*" as a valid token (handled elsewhere).
        if ("*".equals(str)) {
            return true;
        }
        return TOKEN_PATTERN.matcher(str).matches();
    }

