public class URIBuilder {

    // other methods

    /**
     * Normalizes a URI path by ensuring it has at most one leading slash.
     * <p>
     * The original implementation removed all but one leading slash but failed
     * to guarantee that a slash is present when the input did not start with
     * one. This could cause malformed URIs where the path was interpreted as
     * another component (e.g., the host). The revised method now:
     * <ul>
     *   <li>Trims any excess leading slashes, leaving a single slash if any were present.</li>
     *   <li>Prepend a slash if the resulting path does not already start with one.</li>
     *   <li>Leaves an empty path unchanged (no leading slash added).</li>
     * </ul>
     *
     * @param path the raw path component of a URI
     * @return a normalized path, or {@code null} if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Remove any leading slashes beyond the first
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }
        String trimmed = (i > 1) ? path.substring(i - 1) : path;

        // If the path is empty after trimming, return it as-is
        if (trimmed.isEmpty()) {
            return trimmed;
        }

        // Ensure a single leading slash
        if (trimmed.charAt(0) != '/') {
            trimmed = '/' + trimmed;
        }

        return trimmed;
    }

    // other methods

}
