import java.util.regex.Pattern;

public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    // Regex that matches valid ISO‑639 language codes optionally followed by
    // an underscore and a two‑letter ISO‑3166 country code, and an optional
    // variant segment. This is a conservative whitelist that prevents
    // arbitrary strings from being interpreted as locales.
    private static final Pattern VALID_LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2}(_[a-zA-Z]{2}){0,2}$");

    // other methods

    /**
     * Creates a Locale object from the request param, which might
     * be already a Locale or a String. The method validates the
     * string representation against a whitelist to prevent
     * injection of malicious content.
     *
     * @param requestedLocale the parameter from the request
     * @return the Locale or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;
        if (requestedLocale != null) {
            if (requestedLocale instanceof Locale) {
                locale = (Locale) requestedLocale;
            } else {
                String localeStr = requestedLocale.toString().trim();
                if (VALID_LOCALE_PATTERN.matcher(localeStr).matches()) {
                    locale = LocalizedTextUtil.localeFromString(localeStr, null);
                } else {
                    LOG.warn("Invalid locale format received: '{}'. Ignoring.", localeStr);
                }
            }
            if (locale != null) {
                LOG.debug("Applied request locale: {}", locale);
            }
        }
        return locale;
    }

    // other methods

}
