import com.opensymphony.xwork2.util.logging.Logger;
import com.opensymphony.xwork2.util.logging.LoggerFactory;
import java.util.regex.Pattern;

public class DefaultActionMapper implements ActionMapper {

    private static final Logger LOG = LoggerFactory.getLogger(DefaultActionMapper.class);

    /** Whitelist pattern for valid action names – only alphanumerics and a few safe punctuation marks. */
    protected final Pattern allowedActionNames = Pattern.compile("[a-zA-Z0-9._!\\-/]+");

    /** Default action name returned when the supplied name is invalid. */
    private static final String DEFAULT_ACTION_NAME = "default";

    // other methods

    /**
     * Validates the action name against a strict whitelist. If the name does not match,
     * it is rejected and a safe default is returned. This prevents partial sanitisation
     * that could otherwise allow malicious input to slip through.
     *
     * @param rawActionName action name extracted from URI
     * @return a safe action name
     */
    protected String cleanupActionName(final String rawActionName) {
        if (rawActionName == null || rawActionName.isEmpty()) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null or empty action name; using default action.");
            }
            return DEFAULT_ACTION_NAME;
        }

        if (allowedActionNames.matcher(rawActionName).matches()) {
            return rawActionName;
        } else {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Action/method [{}] does not match allowed action names pattern [{}]; rejecting it.",
                         rawActionName, allowedActionNames.pattern());
            }
            // Reject the invalid name and return a safe default
            return DEFAULT_ACTION_NAME;
        }
    }

    // other methods

}
