import org.apache.shiro.realm.ldap.LdapUtils;
import java.io.IOException;
import java.util.Hashtable;
import javax.naming.AuthenticationException;
import javax.naming.CommunicationException;
import javax.naming.Context;
import javax.naming.NamingException;
import javax.naming.ldap.InitialLdapContext;
import javax.naming.ldap.LdapContext;
import javax.naming.ldap.StartTlsRequest;
import javax.naming.ldap.StartTlsResponse;
import org.neo4j.server.security.enterprise.log.SecurityLog;

public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider
{
    private final SecurityLog securityLog;

    // other methods

    /**
     * Creates an {@link LdapContext} that uses STARTTLS and validates the supplied
     * credentials immediately after the TLS negotiation.  The method now performs
     * an explicit bind by executing a lightweight lookup (root DSE).  If the bind
     * fails, the context is closed and a {@link NamingException} is thrown.
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the user DN or bind name
     * @param credentials        the user password
     * @return an authenticated {@link LdapContext}
     * @throws NamingException if the connection or authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                    Object principal,
                                                    Object credentials) throws NamingException {

        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("Principal and credentials must not be null");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        LdapContext ctx = null;
        boolean authenticated = false;

        try {
            // Create an unauthenticated context
            ctx = new InitialLdapContext(env, null);

            // Negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate();

            // Add authentication details to the environment
            ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                                 jndiLdapContextFactory.getAuthenticationMechanism());
            ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
            ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

            // Perform a lightweight lookup to trigger the bind
            ctx.lookup("");

            // If lookup succeeded, authentication was successful
            authenticated = true;
            return ctx;
        } catch (AuthenticationException ae) {
            securityLog.warn(withRealm("LDAP authentication failed for '%s' against '%s': %s",
                                       principal, server(jndiLdapContextFactory), ae.getMessage()));
            throw ae;
        } catch (IOException | NamingException e) {
            securityLog.error(withRealm("Failed to establish TLS connection with '%s': %s",
                                        server(jndiLdapContextFactory), e.getMessage()));
            throw new CommunicationException(e.getMessage(), e);
        } finally {
            if (!authenticated && ctx != null) {
                LdapUtils.closeContext(ctx);
            }
        }
    }

    // other methods
}
