import java.io.InputStream;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.XMLConstants;
import java.io.IOException;

/**
 * Renderer implementation that safely creates XSLT transformers.
 */
public class XsltRenderer implements Renderer {

    // No shared TransformerFactory – each call creates a fresh instance
    // to avoid cross‑thread configuration changes.

    // other methods

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     *
     * <p>Security measures:</p>
     * <ul>
     *   <li>Enables {@code FEATURE_SECURE_PROCESSING} to disable DTDs, external entities,
     *       and other potentially dangerous features.</li>
     *   <li>Explicitly denies access to external DTDs, stylesheets, and schemas by
     *       setting the corresponding {@code ACCESS_EXTERNAL_*} properties to an empty
     *       string.</li>
     *   <li>Validates that the input stream is non‑null before processing.</li>
     * </ul>
     *
     * @param templateStream the XSLT template as an {@link InputStream}
     * @return a securely configured {@link Transformer}
     * @throws IOException if the stream cannot be read or closed
     * @throws ProcessingFailedException if the XSLT is malformed or violates security constraints
     */
    private static Transformer createTransformer(InputStream templateStream)
            throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("templateStream cannot be null");
        }

        // Create a fresh factory for each call to avoid shared mutable state
        TransformerFactory factory = TransformerFactory.newInstance();

        try {
            // Enable secure processing
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Disable external resource access
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            // Build the transformer
            return factory.newTransformer(new StreamSource(templateStream));
        } catch (IllegalArgumentException | TransformerConfigurationException e) {
            // Wrap any configuration errors in a domain‑specific exception
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            // Ensure the stream is always closed
            templateStream.close();
        }
    }

    // other methods

}
