import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Utility class for safely extracting archive entries into a target directory.
 */
public class Expander {

    // other methods

    /**
     * Extracts entries supplied by {@code supplier} into {@code targetDirectory}.
     *
     * <p>All entry names are validated against path‑traversal attacks by resolving
     * them against the canonical target directory and ensuring the resulting
     * path remains within that directory. Absolute paths and names containing
     * suspicious components are rejected outright.</p>
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to an output stream
     * @param targetDirectory the directory into which entries are extracted
     * @throws IOException if extraction fails or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanity checks
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has an empty name");
            }

            // Reject absolute paths – they could escape the target directory.
            if (new File(entryName).isAbsolute()) {
                throw new IOException("absolute entry name not allowed: " + entryName);
            }

            // Resolve the entry against the target directory and normalize.
            Path entryPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still inside the target directory.
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory (and any missing parents).
                Files.createDirectories(entryPath);
            } else {
                // Ensure parent directories exist before writing the file.
                Path parent = entryPath.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }

                // Write the file contents atomically.
                try (OutputStream out = Files.newOutputStream(entryPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods
}
