private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – the data is cached in
    // lastStoredEntry and can be read directly.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // populate lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Defensive checks – a negative size indicates a malformed archive.
    if (csize < 0) {
        throw new IOException("Invalid entry size: " + csize);
    }

    // If the entry has no data, signal EOF immediately.
    if (csize == 0) {
        return -1;
    }

    // If we have already consumed the declared amount of data, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Read data into the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        int l = in.read(buf.array());
        if (l == -1) {
            // Underlying stream ended before the declared size – treat as EOF.
            return -1;
        }
        if (l == 0) {
            // Some streams may return 0 without signalling EOF. To avoid an
            // infinite loop we treat this as a transient condition and
            // attempt to read again. If the next read also returns 0 we
            // throw an exception to surface the problem.
            int retry = in.read(buf.array());
            if (retry <= 0) {
                throw new IOException("Underlying stream returned zero bytes repeatedly");
