import org.xml.sax.XMLReader;
import org.xml.sax.ext.LexicalHandler;
import org.xml.sax.helpers.DefaultHandler;
import org.xml.sax.helpers.XMLReaderFactory;

/**
 * Factory for creating DOM {@link Document}s from SAX streams.
 *
 * <p>This implementation has been hardened against XML External Entity (XXE) attacks by
 * disabling all forms of DTD processing and external entity resolution.  The parser is
 * configured with the following security features:</p>
 * <ul>
 *   <li>Disallow DOCTYPE declarations – prevents any DTD from being parsed.</li>
 *   <li>Disable loading of external DTDs and DTD grammars.</li>
 *   <li>Disable external general and parameter entities.</li>
 * </ul>
 *
 * <p>Any unsupported feature configuration results in an {@link IOException} so that
 * callers are aware of mis‑configured parsers.</p>
 */
public class SAXDocumentFactory extends DefaultHandler implements LexicalHandler, DocumentFactory {

    protected String parserClassName;
    protected XMLReader parser;
    protected Document document;
    protected Node currentNode;
    protected Locator locator;
    protected DocumentType doctype;
    protected boolean isValidating;
    protected ErrorHandler errorHandler;

    // other methods omitted for brevity

    /**
     * Creates a Document.
     *
     * @param is The document input source.
     * @return The parsed {@link Document}.
     * @throws IOException if an error occurs while reading the document or configuring the parser.
     */
    protected Document createDocument(InputSource is) throws IOException {
        try {
            // Instantiate the XMLReader
            if (parserClassName != null) {
                parser = XMLReaderFactory.createXMLReader(parserClassName);
            } else {
                SAXParser saxParser;
                try {
                    saxParser = saxFactory.newSAXParser();
                } catch (ParserConfigurationException pce) {
                    throw new IOException("Could not create SAXParser: " + pce.getMessage(), pce);
                }
                parser = saxParser.getXMLReader();
            }

            // Register handlers
            parser.setContentHandler(this);
            parser.setDTDHandler(this);
            parser.setEntityResolver(this);
            parser.setErrorHandler(errorHandler == null ? this : errorHandler);
            parser.setProperty("http://xml.org/sax/properties/lexical-handler", this);

            /* ---------- Security configuration ---------- */
            // Disable DOCTYPE declarations entirely
            setFeatureSafely(parser, "http://apache.org/xml/features/disallow-doctype-decl", true);

            // Prevent loading of external DTDs and DTD grammars
            setFeatureSafely(parser, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            setFeatureSafely(parser, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

            // Disable external general and parameter entities
            setFeatureSafely(parser, "http://xml.org/sax/features/external-general-entities", false);
            setFeatureSafely(parser, "http://xml.org/sax/features/external-parameter-entities", false);

            // Enable namespaces and namespace prefixes
            setFeatureSafely(parser, "http://xml.org/sax/features/namespaces", true);
            setFeatureSafely(parser, "http://xml.org/sax/features/namespace-prefixes", true);

            // Validation is optional – honour caller's choice
            setFeatureSafely(parser, "http://xml.org/sax/features/validation", isValidating);

            /* -------------------------------------------- */

            // Parse the input source
            parser.parse(is);
        } catch (SAXException e) {
            Throwable cause = e.getException();
            if (cause instanceof InterruptedIOException) {
                throw (InterruptedIOException) cause;
            }
            throw new SAXIOException(e);
        }

        // Reset transient state before returning
        currentNode = null;
        Document ret = document;
        document = null;
        doctype = null;
        locator = null;
        parser = null;
        return ret;
    }

    /**
     * Helper to set a parser feature safely.  Unsupported features result in an
     * {@link IOException} so that callers are notified of misconfiguration.
     */
    private void setFeatureSafely(XMLReader reader, String name, boolean value) throws IOException {
        try {
            reader.setFeature(name, value);
        } catch (SAXNotRecognizedException | SAXNotSupportedException e) {
            throw new IOException("Failed to set parser feature '" + name + "': " + e.getMessage(), e);
        }
    }

    // other methods omitted for brevity
}
