import com.alibaba.fastjson.JSONArray;
import com.alibaba.fastjson.parser.DefaultJSONParser;
import com.alibaba.fastjson.parser.JSONLexer;
import com.alibaba.fastjson.parser.JSONToken;
import com.alibaba.fastjson.parser.deserializer.ObjectDeserializer;
import com.alibaba.fastjson.util.TypeUtils;

/**
 * A custom codec for serializing/deserializing object arrays.
 *
 * <p>
 * The original implementation was vulnerable to Fastjson deserialization attacks
 * because it accepted arbitrary component types (including {@code Object.class})
 * and performed no validation on the incoming JSON.  Attackers could craft
 * payloads that trigger the creation of malicious objects via RMI or other
 * unsafe mechanisms.
 *
 * <p>
 * This patched version introduces a strict whitelist of allowed component
 * types and performs comprehensive checks before delegating to Fastjson's
 * internal parsing logic.  Any attempt to deserialize an array whose component
 * type is not on the whitelist results in an {@link IllegalArgumentException},
 * effectively preventing the exploitation vector.
 *
 * <p>
 * The whitelist includes common immutable types that are safe to deserialize
 * and excludes {@code Object} and other potentially dangerous classes.
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /* Whitelist of safe component types                                    */
    /* --------------------------------------------------------------------- */

    /** Set of component types that are considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES = new HashSet<>(
            Arrays.asList(
                    String.class,
                    Integer.class,
                    Long.class,
                    Double.class,
                    Float.class,
                    Boolean.class,
                    Byte.class,
                    Short.class,
                    Character.class,
                    BigDecimal.class,
                    BigInteger.class,
                    Date.class,
                    UUID.class
            )
    );

    /**
     * Checks whether the supplied component type is allowed.
     *
     * @param cls the component class to check
     * @return {@code true} if the class is in the whitelist
     */
    private boolean isSafeComponentType(Class<?> cls) {
        if (cls == null) {
            return false;
        }
        // Primitive types are inherently safe
        if (cls.isPrimitive()) {
            return true;
        }
        // Allow all classes that are explicitly listed
        return SAFE_COMPONENT_TYPES.contains(cls);
    }

    /* --------------------------------------------------------------------- */
    /* Deserialization logic                                                 */
    /* --------------------------------------------------------------------- */

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        // Handle JSON null
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        // Handle JSON string literal → byte[]
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        Class<?> componentClass;
        Type componentType;

        // Resolve component type for generic arrays
        if (type instanceof GenericArrayType) {
            GenericArrayType gArray = (GenericArrayType) type;
            componentType = gArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type objType = parser.getContext().type;

                if (objType instanceof ParameterizedType) {
                    ParameterizedType pType = (ParameterizedType) objType;
                    Type objRawType = pType.getRawType();
                    Type actualType = null;

                    if (objRawType instanceof Class) {
                        TypeVariable<?>[] params = ((Class<?>) objRawType).getTypeParameters();
                        for (int i = 0; i < params.length; ++i) {
                            if (params[i].getName().equals(typeVar.getName())) {
                                actualType = pType.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    if (actualType instanceof Class) {
                        componentClass = (Class<?>) actualType;
                    } else {
                        componentClass = Object.class;
                    }
                } else {
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else { // Non-generic array
            Class<?> clazz = (Class<?>) type;
            componentType = componentClass = clazz.getComponentType();
        }

        // Reject null or unsafe component types
        if (!isSafeComponentType(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array with component type "
                    + componentClass.getName()
                    + " is not permitted for security reasons."
            );
        }

        JSONArray array = new JSONArray();

        // Parse the JSON array into the temporary JSONArray
        parser.parseArray(componentClass, array, fieldName);

        // Convert JSONArray to a typed array
        return (T) toObjectArray(parser, componentClass, array);
    }

    // ... other methods ...
}
